 0;\n  padding: 0;\n  color: #16222a;\n  background: transparent;\n  outline: none;\n}\n\n.title-input {\n  font-size: 21px;\n  font-weight: 800;\n}\n\n.subtitle-input {\n  color: #596975;\n  font-size: 13px;\n}\n\n.top-actions,\n.stage-toolbar,\n.download-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 8px;\n}\n\n.save-state {\n  color: #687782;\n  font-size: 12px;\n  white-space: nowrap;\n}\n\n.tool-btn,\n.mode-btn {\n  min-height: 32px;\n  border: 1px solid #aebec7;\n  border-radius: 8px;\n  color: #1b2a34;\n  background: #ffffff;\n  cursor: pointer;\n}\n\n.tool-btn {\n  padding: 6px 10px;\n}\n\n.tool-btn.primary {\n  border-color: #2f7d8c;\n  color: #ffffff;\n  background: #2f7d8c;\n}\n\n.tool-btn.danger {\n  border-color: #c55353;\n  color: #8b2323;\n}\n\n.tool-btn:disabled {\n  opacity: 0.48;\n  cursor: not-allowed;\n}\n\n.workspace {\n  min-height: 0;\n  display: grid;\n  grid-template-columns: 250px minmax(0, 1fr) 280px;\n}\n\n.left-panel,\n.right-panel {\n  min-height: 0;\n  overflow: auto;\n  border-right: 1px solid #bdc8cf;\n  padding: 10px;\n  background: #f3f6f7;\n  display: grid;\n  align-content: start;\n  gap: 10px;\n}\n\n.right-panel {\n  border-right: 0;\n  border-left: 1px solid #bdc8cf;\n}\n\n.panel-section {\n  border: 1px solid #c8d2d8;\n  border-radius: 8px;\n  padding: 10px;\n  background: #ffffff;\n  display: grid;\n  gap: 10px;\n}\n\n.panel-section h2 {\n  margin: 0;\n  color: #23313a;\n  font-size: 14px;\n}\n\n.tool-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 8px;\n}\n\n.mode-btn {\n  padding: 8px;\n  display: grid;\n  grid-template-columns: 24px minmax(0, 1fr);\n  gap: 6px;\n  align-items: center;\n  text-align: left;\n}\n\n.mode-btn[aria-pressed='true'] {\n  border-color: #2f7d8c;\n  box-shadow: 0 0 0 2px rgba(47, 125, 140, 0.16);\n}\n\n.mode-icon {\n  width: 24px;\n  height: 24px;\n  border-radius: 8px;\n  color: #ffffff;\n  background: #45606e;\n  display: grid;\n  place-items: center;\n  font-size: 12px;\n  font-weight: 800;\n}\n\n.hint-line,\n.empty-state,\n.modal-head p {\n  margin: 0;\n  color: #63727d;\n  font-size: 12px;\n  line-height: 1.55;\n}\n\n.field,\n.swatch-field {\n  display: grid;\n  gap: 6px;\n}\n\n.field span,\n.swatch-field span,\n.toggle-line span {\n  color: #60707c;\n  font-size: 12px;\n}\n\n.field input,\n.field textarea,\n.field select,\n.select-input {\n  width: 100%;\n  border: 1px solid #b9c6ce;\n  border-radius: 8px;\n  padding: 7px 8px;\n  color: #20313d;\n  background: #fbfdfd;\n  outline: none;\n}\n\n.field textarea {\n  resize: vertical;\n}\n\n.toggle-line {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n}\n\n.swatch-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 8px;\n}\n\n.swatch-field input {\n  width: 100%;\n  height: 34px;\n  border: 1px solid #b9c6ce;\n  border-radius: 8px;\n  padding: 3px;\n  background: #ffffff;\n}\n\n.swatch-field.wide {\n  grid-template-columns: minmax(0, 1fr) 64px;\n  align-items: center;\n}\n\n.stage-panel {\n  min-width: 0;\n  min-height: 0;\n  padding: 10px;\n  background: #d9e2e6;\n  display: grid;\n  grid-template-rows: auto minmax(0, 1fr);\n  gap: 10px;\n}\n\n.stage-toolbar {\n  justify-content: flex-start;\n  border: 1px solid #bdc8cf;\n  border-radius: 8px;\n  padding: 8px;\n  background: #f8fafb;\n}\n\n.stage-toolbar span {\n  color: #596975;\n  font-size: 12px;\n}\n\n.map-viewport {\n  min-height: 0;\n  overflow: hidden;\n  border: 1px solid #aebec7;\n  border-radius: 8px;\n  background: #aebec7;\n  cursor: crosshair;\n  touch-action: none;\n}\n\n.map-canvas {\n  display: block;\n  width: 100%;\n  height: 100%;\n}\n\n.map-element {\n  cursor: grab;\n  transition: filter 120ms ease, opacity 120ms ease;\n}\n\n.map-element:hover {\n  filter: drop-shadow(0 0 5px rgba(21, 93, 112, 0.42));\n}\n\n.map-element.selected {\n  filter: drop-shadow(0 0 7px rgba(229, 106, 53, 0.8));\n}\n\n.element-list {\n  max-height: 220px;\n  overflow: auto;\n  display: grid;\n  gap: 6px;\n}\n\n.element-row {\n  width: 100%;\n  border: 1px solid #c8d2d8;\n  border-radius: 8px;\n  padding: 7px 8px;\n  color: #20313d;\n  background: #fbfdfd;\n  display: grid;\n  grid-template-columns: 44px minmax(0, 1fr);\n  gap: 8px;\n  text-align: left;\n  cursor: pointer;\n}\n\n.element-row span {\n  color: #71808b;\n  font-size: 12px;\n}\n\n.element-row strong {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-size: 13px;\n}\n\n.element-row[aria-pressed='true'] {\n  border-color: #2f7d8c;\n  background: #eaf6f7;\n}\n\n.property-panel {\n  align-content: start;\n}\n\n.inline-grid {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) auto;\n  gap: 10px;\n  align-items: end;\n}\n\n.property-toggle {\n  min-height: 35px;\n}\n\n.hidden-file {\n  display: none;\n}\n\n.modal-backdrop {\n  position: fixed;\n  inset: 0;\n  z-index: 30;\n  padding: 18px;\n  background: rgba(7, 12, 18, 0.58);\n  display: grid;\n  place-items: center;\n}\n\n.export-modal {\n  width: min(980px, 100%);\n  max-height: min(760px, calc(100dvh - 36px));\n  border: 1px solid #c8d2d8;\n  border-radius: 8px;\n  padding: 14px;\n  background: #ffffff;\n  display: grid;\n  grid-template-rows: auto auto minmax(0, 1fr);\n  gap: 12px;\n}\n\n.modal-head {\n  display: flex;\n  justify-content: space-between;\n  gap: 12px;\n}\n\n.modal-head h2 {\n  margin: 0 0 4px;\n  font-size: 18px;\n}\n\n.download-row {\n  justify-content: flex-start;\n}\n\n.export-code {\n  width: 100%;\n  min-height: 0;\n  border: 1px solid #b9c6ce;\n  border-radius: 8px;\n  padding: 10px;\n  color: #dce8ec;\n  background: #121922;\n  resize: none;\n  font-family: Consolas, 'Courier New', monospace;\n  font-size: 12px;\n  line-height: 1.55;\n}\n\n@media (max-width: 980px) {\n  .workspace {\n    grid-template-columns: 210px minmax(0, 1fr);\n  }\n\n  .right-panel {\n    grid-column: 1 / -1;\n    border-top: 1px solid #bdc8cf;\n    border-left: 0;\n    max-height: 280px;\n  }\n}\n\n@media (max-width: 720px) {\n  .topbar {\n    grid-template-columns: 1fr;\n  }\n\n  .top-actions {\n    justify-content: flex-start;\n  }\n\n  .workspace {\n    grid-template-columns: 1fr;\n  }\n\n  .left-panel {\n    max-height: 320px;\n  }\n\n  .stage-panel {\n    min-height: 520px;\n  }\n}\n"],"sourceRoot":""}]);
